       "f": "=ROUND($B$29*(1+$B$30)^(B$69-1),0)*($B$27*(1-$B$28))*12*(1-$B$19)-$B$40+MAX($B$45,$B$42/IF($B$41=\"per 1M tokens\",1000000,IF($B$41=\"per 1K tokens\",1000,1))*$B$43*(1-$B$44))*12"
